(()=>{const rows=[];for(const mode of ['visible','group-hidden','text-hidden','svg-hidden','ancestor-hidden','visibility-hidden','detached']){const div=document.createElement('div');div.innerHTML='<svg><g><text x="32" y="32">abcd</text></g></svg>';document.body.appendChild(div);const svg=div.firstChild,g=svg.firstChild,t=g.firstChild;t.getComputedTextLength();if(mode==='group-hidden')g.style.display='none';if(mode==='text-hidden')t.style.display='none';if(mode==='svg-hidden')svg.style.display='none';if(mode==='ancestor-hidden')div.style.display='none';if(mode==='visibility-hidden')g.style.visibility='hidden';if(mode==='detached')div.remove();const out={mode,lengthZero:t.getComputedTextLength()===0,chars:t.getNumberOfChars()};try{out.extent=t.getExtentOfChar(0).width===0}catch(e){out.extent=e.name}rows.push(out);div.remove()}const f=document.createElement('iframe');document.body.appendChild(f);f.contentDocument.body.innerHTML='<svg><text>abcd</text></svg>';const t=f.contentDocument.querySelector('text');rows.push({mode:'frame-visible',lengthZero:t.getComputedTextLength()===0});f.style.display='none';rows.push({mode:'frame-hidden',lengthZero:t.getComputedTextLength()===0});f.remove();rows.push({mode:'frame-detached',lengthZero:t.getComputedTextLength()===0});const host=document.createElement('div');document.body.appendChild(host);const shadow=host.attachShadow({mode:'open'}),sf=document.createElement('iframe');shadow.appendChild(sf);sf.contentDocument.body.innerHTML='<svg><text>abcd</text></svg>';const st=sf.contentDocument.querySelector('text');rows.push({mode:'shadow-frame-visible',lengthZero:st.getComputedTextLength()===0});host.style.display='none';rows.push({mode:'shadow-frame-hidden',lengthZero:st.getComputedTextLength()===0});host.remove();return {rows}})()